function countSmallerElements(arr) {
  const result = new Array(arr.length).fill(0);
  const sorted = [];

  for (let i = arr.length - 1; i >= 0; i--) {
    // Найдем позицию, где можно вставить arr[i] в отсортированный список
    // чтобы сохранить порядок (от большего к меньшему)
    let pos = binarySearch(sorted, arr[i]);

    // Количество элементов, меньших arr[i], это позиция
    result[i] = pos;

    // Вставляем arr[i] в отсортированный список
    sorted.splice(pos, 0, arr[i]);
  }

  return result;
}

