### ✅ 示例：支持多次撤消和前进的类

```csharp
using System;
using System.Collections.Generic;

public class UndoRedoManager<T>
{
    private Stack<T> undoStack = new Stack<T>();  // 保存撤销状态
    private Stack<T> redoStack = new Stack<T>();  // 保存重做状态
    private T currentState;                      // 当前状态

    public void Do(T state)
    {
        // 将当前状态压入 undoStack
        undoStack.Push(currentState);
        // 清空 redoStack，因为重做状态已失效
        redoStack.Clear();
        // 更新当前状态
        currentState = state;
    }

    public T Undo()
    {
        if (undoStack.Count == 0)
            throw new InvalidOperationException("No more undo steps available.");

        // 从 undoStack 弹出上一个状态
        T previousState = undoStack.Pop();
        // 将当前状态压入 redoStack
        redoStack.Push(currentState);
        // 更新当前状态
        currentState = previousState;
        return currentState;
    }

    public T Redo()
    {
        if (redoStack.Count == 0)
            throw new InvalidOperationException("No more redo steps available.");

        // 从 redoStack 弹出上一个状态
        T nextState = redoStack.Pop();
        // 将当前状态压入 undoStack
        undoStack.Push(currentState);
        // 更新当前状态
        currentState = nextState;
        return currentState;
    }

    public T CurrentState => currentState;
}
```

